import {top,petCard,shell,onb,chevron,picker} from './screens.js';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const A=(id,cls='')=>`<img class="ui-asset ${cls}" src="./assets/records/${id.replace(':','-')}.svg" alt="" data-figma-asset="${id}">`;
const surface=id=>A(id,'ui-surface');
const day=t=>new Date(t).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});
const local=t=>{const d=new Date(t);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const weights=(c,pid=c.pet?.id)=>c.state.records.filter(r=>r.petId===pid&&r.activity==='体重').sort((a,b)=>new Date(b.at)-new Date(a.at));
const change=(value,prev)=>prev?(Number(value)-Number(prev.value)>=0?'+':'')+(Number(value)-Number(prev.value)).toFixed(2)+' kg':'暂无对比';
const range=p=>p?.weightMin&&p?.weightMax?`${p.weightMin}–${p.weightMax} kg`:'未设置';
const home=()=>`<div class="ui-form-home">${onb(3105)}</div>`;
function datetime(time){const t=local(time);return `<input name="at" type="hidden" value="${t}"><div class="rec-datetime"><label>${surface('1667:3714')}<strong>日期</strong><span id="recordDateDisplay">${day(time)}</span><input name="date" type="date" aria-label="记录日期" required value="${t.slice(0,10)}">${chevron()}</label><label>${surface('1667:3715')}<strong>时间</strong><input name="time" type="time" aria-label="记录时间" required value="${t.slice(11)}">${chevron()}</label></div>`;}
function note(value,id){return `<label class="rec-note">${surface(id)}<strong>备注</strong><textarea name="note" aria-label="备注" maxlength="500" placeholder="记录它今天的小日常…">${E(value||'')}</textarea></label>`;}
function photos(values){return `<h2 class="rec-photo-title">照片（可选）</h2><div class="rec-photos"><div id="photos">${values.map(p=>`<img src="${E(p)}" alt="记录照片">`).join('')}</div><label class="rec-upload">${surface('1667:3763')}${A('1667:3818')}<input id="photoInput" type="file" accept="image/*" multiple hidden aria-label="添加照片"></label><label class="rec-upload">${surface('1667:3764')}<span>＋</span><input class="rec-extra-photo" type="file" accept="image/*" multiple hidden aria-label="再添加照片"></label></div>`;}
function record(c){if(c.completeId)return null;if(!['体重','喂食'].includes(c.activity))return generalRecord(c);const r=c.state.records.find(r=>r.id===c.editId),p=r?c.state.pets.find(p=>p.id===r.petId):c.pet;if(!p)return null;const isWeight=c.activity==='体重',previous=weights(c,p.id).find(x=>x.id!==r?.id&&new Date(x.at)<new Date(r?.at||Date.now()));const initial=r?.value||previous?.value||'';return shell(top(c,(r?'编辑':'记录')+c.activity,r?'detail':c.origin,true)+petCard(p)+`<form id="recordForm" class="rec-form ${isWeight?'rec-weight-form':'rec-feed-form'}"><input name="petId" type="hidden" value="${E(p.id)}">${isWeight?`<div class="rec-weight-entry">${surface('1667:3717')}<strong>体重（kg）</strong><button type="button" data-weight-step="-0.05" aria-label="减少体重">${A('1672:274')}</button><div><input name="value" type="number" min="0.01" max="1000" step="0.01" required aria-label="体重（kg）" placeholder="—" value="${E(initial)}"><span>kg</span></div><button type="button" data-weight-step="0.05" aria-label="增加体重">${A('1671:8117')}</button><small id="previousWeight">${previous?`上次：${E(previous.value)} kg（${day(previous.at)}）`:'还没有上次记录'}</small></div>`:''}${datetime(r?.at||Date.now())}${isWeight?'':`<label class="rec-food-row">${surface('1667:3760')}<strong>食物</strong><input name="product" required maxlength="100" aria-label="食物" placeholder="输入食物名称" value="${E(r?.product||'')}">${chevron()}</label><label class="rec-food-row">${surface('1667:3761')}<strong>食用量</strong><input name="value" required type="number" min="0.01" step="0.01" aria-label="食用量" value="${E(r?.value||'')}"><select name="unit" aria-label="食用量单位">${['g','ml','份'].map(x=>`<option ${(r?.unit||'g')===x?'selected':''}>${x}</option>`).join('')}</select>${chevron()}</label>`}${note(r?.note,isWeight?'1667:3713':'1667:3762')}${isWeight?`<div class="rec-comparison">${surface('1667:3720')}<div><small>较上次</small><b id="weightChange">${initial?change(initial,previous):'—'}</b></div><button type="button" id="setWeightTarget"><small>目标范围</small><b id="weightTargetText">${range(p)}</b></button></div>`:photos(c.photos)+`<label class="rec-toggle-row">${surface('1667:3765')}<span>关联用品库存</span><input id="linkInventory" type="checkbox" role="switch" aria-label="关联用品库存"><span class="ui-toggle"></span></label>${!r?`<label class="rec-toggle-row">${surface('1667:3768')}<span>设置下次提醒</span><input name="next" type="checkbox" role="switch" aria-label="设置下次提醒"><span class="ui-toggle"></span></label>`:''}<button type="submit" class="rec-feed-save">${surface('1667:3771')}<span>保存记录</span></button>`}${isWeight?`<button type="submit" class="rec-weight-save">${surface('1667:3721')}<span>保存体重</span></button>`:''}</form>`+home(),'record-entry',isWeight?'rec-weight':'rec-feed');}
function generalRecord(c){const r=c.state.records.find(x=>x.id===c.editId),p=r?c.state.pets.find(x=>x.id===r.petId):c.pet;if(!p)return null;const a=c.activity,medicine=['驱虫','疫苗','用药'].includes(a),walk=['散步','遛狗'].includes(a),writing=['日记','随手日记','照片'].includes(a);const field=(name,label,value,placeholder,type='text',unit='')=>`<label class="rec-food-row">${surface('1667:3760')}<strong>${label}</strong><input name="${name}" type="${type}" ${type==='number'?'min="0.01" step="0.01"':''} maxlength="100" aria-label="${label}" placeholder="${placeholder}" value="${E(value||'')}">${unit?`<span>${unit}</span><input name="unit" type="hidden" value="${unit}">`:''}${chevron()}</label>`;const fields=writing?'':medicine?field('product',a==='疫苗'?'疫苗名称':'产品名称',r?.product,'输入名称')+field('dose','实际剂量',r?.dose,'填写实际使用剂量'):walk?field('value','时长',r?.value,'选填','number','分钟')+field('product','活动情况',r?.product,'记录本次活动情况'):field('product',a==='换水'?'换水情况':a==='排便'?'排便情况':'实际情况',r?.product,`记录本次${a}的情况`);return shell(top(c,(r?'编辑':'记录')+a,r?'detail':c.origin,true)+petCard(p)+`<form id="recordForm" class="rec-form rec-generic-form"><input name="petId" type="hidden" value="${E(p.id)}">${datetime(r?.at||Date.now())}${fields}${note(r?.note,'1667:3762')}${photos(c.photos)}${!r?`<label class="rec-toggle-row">${surface('1667:3768')}<span>设置下次提醒</span><input name="next" type="checkbox" role="switch" aria-label="设置下次提醒"><span class="ui-toggle"></span></label>`:''}<p class="rec-help">记录实际发生的事情，可以补录过去。</p><button type="submit" class="rec-feed-save">${surface('1667:3771')}<span>保存记录</span></button></form>`+home(),'record-entry','rec-generic');}
function detail(c){const r=c.state.records.find(x=>x.id===c.editId);if(!r)return null;return shell(top(c,'记录详情',c.origin,true)+petCard(c.state.pets.find(p=>p.id===r.petId))+`<div class="rec-detail-number"><strong>${r.activity}</strong><div><b>${E(r.value||(['体重','喂食'].includes(r.activity)?'—':'已记录'))}</b><span>${r.activity==='体重'?'kg':E(r.unit||(r.activity==='喂食'?'g':''))}</span>${r.product||r.dose?`<small>${E([r.product,r.dose].filter(Boolean).join(' · '))}</small>`:''}</div><time>${new Date(r.at).toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'})} · ${new Date(r.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}</time></div><div class="rec-detail-note">${surface('1667:3814')}<strong>备注</strong><p>${E(r.note||'暂无备注')}</p></div><label class="rec-detail-photo">${surface('1667:3815')}${r.photos?.length?`<span class="rec-photo-gallery">${r.photos.map(p=>`<img src="${E(p)}" alt="记录照片">`).join('')}</span>`:`${A('1667:3818')}<span>添加照片(选填)</span>`}<input id="detailPhotoInput" type="file" accept="image/*" multiple hidden aria-label="添加记录照片"></label><button id="editRecord" class="rec-detail-edit">${surface('1667:3827')}<span>编辑记录</span></button><button id="deleteRecord" class="rec-detail-delete">${surface('1667:3830')}<span>删除记录</span></button>`+home(),'record-detail');}
function trend(list){if(!list.length)return `<div class="rec-chart-empty">记录第一次体重，开始观察变化。</div>`;const rows=list.slice(0,10).reverse(),vals=rows.map(r=>Number(r.value)),min=Math.floor((Math.min(...vals)-.15)*10)/10,max=Math.ceil((Math.max(...vals)+.15)*10)/10,span=max-min||1;const first=new Date(rows[0].at).getTime(),last=new Date(rows.at(-1).at).getTime();const points=rows.map(r=>[64+(last===first?143:(new Date(r.at)-first)/(last-first)*287),495-(Number(r.value)-min)/span*95]);return `<svg class="rec-trend" viewBox="0 0 402 199" role="img" aria-label="实际体重变化趋势"><g transform="translate(0,-347)">${[0,1,2,3].map(i=>{const y=495-i*95/3;return `<line x1="64" x2="351" y1="${y}" y2="${y}" stroke="#dbdee4"/><text x="38" y="${y+4}" font-size="12" fill="#54555a">${(min+span*i/3).toFixed(1)}</text>`;}).join('')}${rows.length>1?`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#713f12" stroke-width="2"/>`:''}${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3.2" fill="#fff" stroke="#713f12" stroke-width="1.7"/>${i===0||i===points.length-1||i===Math.floor(points.length/2)&&p[0]-points[0][0]>45&&points.at(-1)[0]-p[0]>45?`<text x="${p[0]}" y="513" text-anchor="middle" font-size="10" fill="#54555a">${new Date(rows[i].at).getMonth()+1}/${new Date(rows[i].at).getDate()}</text>`:""}`).join('')}</g></svg>`;}
function health(c){if(!c.pet)return null;const rows=weights(c),last=rows[0],prev=rows[1],category=c.healthTab||'体重';return shell(top(c,'健康档案','profile')+`<div class="rec-health-picker">${picker(c)}</div><div class="rec-health-tabs">${['体重','疫苗驱虫','用药就诊'].map(x=>`<button data-health-tab="${x}" class="${category===x?'active':''}">${x}</button>`).join('')}</div>${category==='体重'?`<div class="rec-health-summary">${surface('1667:3193')}<small>${E(c.pet.name)} · ${last?day(last.at)+'测量':'尚未测量'}</small><div><b>${E(last?.value||'—')}</b><span>kg</span></div><small>${last?'较上次 '+change(last.value,prev):'添加第一条体重记录'}</small></div><div class="rec-chart-heading"><strong>体重变化（kg）</strong><span><i></i>体重（kg）</span></div>${trend(rows)}<button id="setWeightTarget" class="rec-health-target">${surface('1667:3260')}<strong>目标体重范围</strong><span id="weightTargetText">${range(c.pet)}</span></button><div class="rec-history-heading"><h2>历史记录</h2><button id="weightReminder">${A('1667:3275','ui-surface')}<span>设置提醒</span></button></div><div class="rec-weight-history">${rows.length?rows.map(r=>`<button data-detail="${E(r.id)}"><span>${day(r.at)}</span><span>${E(r.value)}kg</span></button>`).join(''):'<p>暂无历史记录</p>'}</div><button id="addWeight" class="rec-health-add">${surface('1667:3259')}<span>记录体重</span></button>`:`<div class="rec-health-category"><h2>${category}</h2>${c.state.records.filter(r=>r.petId===c.pet.id&&(category==='疫苗驱虫'?['疫苗','驱虫']:['用药','就诊','复诊']).includes(r.activity)).sort((a,b)=>new Date(b.at)-new Date(a.at)).map(r=>`<button data-detail="${E(r.id)}"><strong>${E(r.activity)}</strong><small>${day(r.at)} · ${E(r.product||r.note||'已记录')}</small></button>`).join('')||'<p>这个分类还没有记录。</p>'}<button data-add="health">＋ 新建记录</button></div>`}`+home(),'health','rec-health');}
export function renderRecordPage(page,c){return ({recordform:record,detail,health}[page])?.(c)??null;}
